const data = $input.first().json.body || $input.first().json;

// We only want to embed completed jobs with a GCS URI
if (data.status !== 'completed') {
  return [{ json: { skip: true, reason: `Job status is ${data.status}` } }];
}

// GCS URI looks like gs://bucket/path.mp3
// We need to convert it to a public https URL
let audioUrl = '';
if (data.gcs_uri && data.gcs_uri.startsWith('gs://')) {
    const parts = data.gcs_uri.replace('gs://', '').split('/');
    const bucket = parts.shift();
    const objectPath = parts.join('/');
    audioUrl = `https://storage.googleapis.com/${bucket}/${objectPath}`;
} else {
    return [{ json: { skip: true, reason: 'No valid GCS URI found in callback' } }];
}

// We embedded the postId inside the jobId using the format {siteSlug}-{postId}-{slug}
// For example: ghost-founderreality-com-64b7f9c8a2b3d4e5f6a7b8c9-my-article-slug
const jobIdParts = data.job_id.split('-');

// We need to find the 24-char hex string which is the Ghost Post ID
const postIdIndex = jobIdParts.findIndex(part => part.length === 24 && /^[0-9a-fA-F]+$/.test(part));

if (postIdIndex === -1) {
    return [{ json: { skip: true, reason: 'Could not extract post ID from job ID' } }];
}

const postId = jobIdParts[postIdIndex];
const siteSlug = jobIdParts.slice(0, postIdIndex).join('-');

return [{
  json: {
    skip: false,
    jobId: data.job_id,
    postId,
    siteSlug,
    audioUrl
  }
}];

// Get the admin API key from environment
const apiKey = $json.siteSlug.includes('founderreality') 
  ? $env.GHOST_SITE1_ADMIN_API_KEY 
  : $env.GHOST_SITE2_ADMIN_API_KEY;

// Split the key into id and secret (format: key_id:secret)
const [keyId, secret] = apiKey.split(':');

if (!keyId || !secret) {
  throw new Error('Invalid Ghost Admin API key format. Expected: key_id:secret');
}

// Create JWT header and payload
const header = {
  alg: 'HS256',
  typ: 'JWT'
};

const payload = {
  iat: Math.floor(Date.now() / 1000),
  exp: Math.floor(Date.now() / 1000) + (5 * 60), // 5 minutes expiry
  aud: '/admin/'
};

// Base64url encode without padding
function base64url(str) {
  return Buffer.from(str).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
}

const encodedHeader = base64url(JSON.stringify(header));
const encodedPayload = base64url(JSON.stringify(payload));

// Sign using HMAC-SHA256
const crypto = require('crypto');
const signatureInput = `${encodedHeader}.${encodedPayload}`;
const signature = crypto.createHmac('sha256', secret).update(signatureInput).digest('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');

const jwt = `${signatureInput}.${signature}`;

return [{
  json: {
    ...$json,
    ghostJwtToken: jwt
  }
}];

const postData = $input.first().json;
const post = postData.posts?.[0];

if (!post) {
    throw new Error('Ghost API did not return a post');
}

// We need the data from the parse-callback node
const parsed = $('Check Status & Parse Job ID').first().json;

// Don't inject again if there's already an audio player added by this script
let html = post.html || '';
if (html.includes('id="gn-audio-embed"')) {
    return [{ json: { skipUpdate: true, reason: 'Audio embed already present' } }];
}

// The audio widget HTML
const audioWidget = `
<div id="gn-audio-embed" style="margin-bottom: 24px; padding: 16px; background-color: #f8f9fa; border-radius: 8px; border: 1px solid #e9ecef;">
    <p style="margin-top: 0; margin-bottom: 8px; font-weight: 600; font-size: 0.9em; color: #495057;">🎧 Listen to this article (AI Narrated)</p>
    <audio controls style="width: 100%; height: 40px;">
        <source src="${parsed.audioUrl}" type="audio/mpeg">
        Your browser does not support the audio element.
    </audio>
</div>
`;

const newHtml = audioWidget + html;

return [{
  json: {
    skipUpdate: false,
    postId: post.id,
    updatedAt: post.updated_at,
    siteSlug: parsed.siteSlug,
    newHtml
  }
}];
